(() => {
  'use strict';

  const escapeHtml = value => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

  const jsString = value => JSON.stringify(String(value ?? '')).replace(/</g, '\\u003c');
  const number = value => Number(value) || 0;

  function optionMarkup(options, selectedValue) {
    return (options || []).map(option => {
      const value = String(option.value ?? '');
      const selected = String(selectedValue ?? '') === value ? ' selected' : '';
      return `<option value="${escapeHtml(value)}"${selected}>${escapeHtml(option.label ?? value)}</option>`;
    }).join('');
  }

  function participantsMarkup(participants = {}) {
    const logoResolver = typeof participants.logoResolver === 'function'
      ? participants.logoResolver
      : () => 'escudo.webp';
    const shortResolver = typeof participants.shortResolver === 'function'
      ? participants.shortResolver
      : team => team?.abbreviation || team?.name || team?.equipe || '—';
    const nameResolver = typeof participants.nameResolver === 'function'
      ? participants.nameResolver
      : team => team?.name || team?.equipe || String(team || 'A definir');

    if (participants.mode === 'groups') {
      const groups = Array.isArray(participants.groups) ? participants.groups : [];
      if (!groups.length) return `<div class="groups-container" id="${escapeHtml(participants.containerId || 'groups-container')}"></div>`;
      return `<div class="groups-container" id="${escapeHtml(participants.containerId || 'groups-container')}">${groups.map(group => {
        const teams = Array.isArray(group.teams) ? group.teams : [];
        return `<div class="group-card-simple"><div class="group-header-simple">${escapeHtml(group.label || group.name || 'Grupo')}</div><ul class="group-list">${teams.map(team => {
          const full = nameResolver(team);
          const logo = logoResolver(full, team) || 'escudo.webp';
          return `<li><img loading="lazy" decoding="async" src="${escapeHtml(logo)}" class="team-logo" alt="${escapeHtml(full)}" onerror="this.onerror=null;this.src='escudo.webp'"><span class="clickable" onclick="if(window.openTeamProfile) window.openTeamProfile(${jsString(full)})">${escapeHtml(full)}</span></li>`;
        }).join('')}</ul></div>`;
      }).join('')}</div>`;
    }

    const teams = Array.isArray(participants.teams) ? participants.teams : [];
    return `<div class="ffws-season-participants-grid">${teams.map(team => {
      const full = nameResolver(team);
      const short = shortResolver(team);
      const logo = logoResolver(full, team) || 'escudo.webp';
      return `<button type="button" class="group-card-simple ffws-season-participant-card" onclick="if(window.openTeamProfile) window.openTeamProfile(${jsString(full)})" title="Abrir perfil de ${escapeHtml(full)}">
        <ul class="group-list"><li>
          <img loading="lazy" decoding="async" src="${escapeHtml(logo)}" class="team-logo" alt="${escapeHtml(full)}" onerror="this.onerror=null;this.src='escudo.webp'">
          <span class="ffws-season-participant-full">${escapeHtml(full)}</span>
          <span class="ffws-season-participant-short">${escapeHtml(short)}</span>
        </li></ul>
      </button>`;
    }).join('')}</div>`;
  }

  function formatMarkup(format = {}) {
    const legends = Array.isArray(format.legends) ? format.legends : [];
    const details = format.details || null;
    return `<div class="br-stage-format-panel${format.extraClass ? ` ${escapeHtml(format.extraClass)}` : ''}"${format.id ? ` id="${escapeHtml(format.id)}"` : ''}>
      <div class="br-stage-format-head"><div>
        <div class="br-stage-kicker">${escapeHtml(format.kicker || '')}</div>
        <h3>${escapeHtml(format.title || '')}</h3>
        <p>${escapeHtml(format.description || '')}</p>
      </div></div>
      <div class="br-stage-legend">${legends.map(legend => `<div class="br-legend-row ${escapeHtml(legend.className || '')}"><span class="br-legend-line"></span><strong>${escapeHtml(legend.range || '')}</strong> ${escapeHtml(legend.label || '')}</div>`).join('')}</div>
      ${details ? `<details class="br-champion-rush-box"><summary>${escapeHtml(details.summary || 'Ver detalhes')}</summary><div class="br-champion-rush-content">${details.intro ? `<p>${details.intro}</p>` : ''}${Array.isArray(details.items) ? `<ul>${details.items.map(item => `<li>${item}</li>`).join('')}</ul>` : ''}</div></details>` : ''}
    </div>`;
  }

  function filterMarkup(filters = {}) {
    const period = filters.period || {};
    const map = filters.map || {};
    const drop = filters.drop || {};

    const periodControl = period.mode === 'container'
      ? `<div class="day-filters" id="${escapeHtml(period.containerId || 'season-day-filters')}"></div>`
      : `<select id="${escapeHtml(period.id || 'season-period-filter')}" onchange="${escapeHtml(period.onchange || '')}">${optionMarkup(period.options, period.selected)}</select>`;

    const mapControl = `<select id="${escapeHtml(map.id || 'season-map-filter')}" onchange="${escapeHtml(map.onchange || '')}">${optionMarkup(map.options, map.selected)}</select>`;

    const dropHidden = drop.visible === false ? ' style="margin-top:-10px;display:none;"' : ' style="margin-top:-10px;"';
    return `<div class="filters ffws-season-filters">
      <label style="color:var(--text-muted);font-weight:bold;">${escapeHtml(period.label || 'Filtrar por Dias:')}</label>
      ${periodControl}
      <label class="ffws-season-map-label" style="color:var(--text-muted);font-weight:bold;margin-left:auto;">${escapeHtml(map.label || 'Mapa:')}</label>
      ${mapControl}
    </div>
    <div class="filters" id="${escapeHtml(drop.containerId || 'season-drop-filter-container')}"${dropHidden}>
      <label style="color:var(--accent);font-weight:bold;">${escapeHtml(drop.label || 'Queda Específica:')}</label>
      <select id="${escapeHtml(drop.id || 'season-drop-filter')}" onchange="${escapeHtml(drop.onchange || '')}" style="flex:1;max-width:300px;">${optionMarkup(drop.options, drop.selected)}</select>
    </div>`;
  }

  function zoneForPosition(position, zones) {
    const pos = number(position);
    if (!pos) return null;
    return (zones || []).find(zone => pos >= number(zone.from) && pos <= number(zone.to)) || null;
  }

  function valueForColumn(row, column, hasData) {
    if (column.key === 'position') return number(row.position) || '—';
    if (column.key === 'team') return row.team || 'A definir';
    if (!hasData && column.emptyValue !== undefined) return column.emptyValue;
    if (!hasData) return '—';
    const raw = typeof column.value === 'function' ? column.value(row) : row[column.key];
    if (typeof column.format === 'function') return column.format(raw, row);
    return raw ?? '—';
  }

  function teamCellMarkup(row, table) {
    const resolveName = typeof table.resolveTeamName === 'function' ? table.resolveTeamName : value => value;
    const resolveShort = typeof table.resolveShortName === 'function' ? table.resolveShortName : value => value;
    const resolveLogo = typeof table.resolveLogo === 'function' ? table.resolveLogo : () => 'escudo.webp';
    const full = resolveName(row.team) || row.team || 'A definir';
    const short = resolveShort(full) || full;
    const logo = resolveLogo(full) || 'escudo.webp';
    return `<td class="team-cell">
      <img loading="lazy" decoding="async" src="${escapeHtml(logo)}" class="team-logo team-logo-mobile-full clickable" alt="${escapeHtml(full)}" onerror="this.onerror=null;this.src='escudo.webp'" onclick="if(window.openTeamProfile) window.openTeamProfile(${jsString(full)})">
      <span class="clickable full-name-desktop" onclick="if(window.openTeamProfile) window.openTeamProfile(${jsString(full)})">${escapeHtml(full)}</span>
      <span class="clickable short-name-mobile" onclick="if(window.openTeamProfile) window.openTeamProfile(${jsString(full)})">${escapeHtml(short)}</span>
    </td>`;
  }

  function tableMarkup(table = {}) {
    const columns = Array.isArray(table.columns) ? table.columns : [];
    const rows = Array.isArray(table.rows) ? table.rows : null;
    const tableId = table.id || 'season-standings-table';
    const toggleButton = table.mobileToggle === false ? '' : `<button class="btn-action hide-on-desktop" onclick="const table=document.getElementById('${escapeHtml(tableId)}');table.classList.toggle('full-view');this.innerText=this.innerText==='Ver Tabela Completa'?'Ocultar Detalhes':'Ver Tabela Completa';" style="width:100%;margin-bottom:12px;">Ver Tabela Completa</button>`;

    const head = columns.map((column, index) => {
      const classes = [column.className || '', column.hideMobile ? 'hide-mobile' : ''].filter(Boolean).join(' ');
      const sort = column.sort === false ? '' : ` onclick="sortTable('${escapeHtml(tableId)}',${index},${column.numeric === false ? 'false' : 'true'})"`;
      const id = column.id ? ` id="${escapeHtml(column.id)}"` : '';
      const style = column.key === 'team' ? ' style="text-align:center;"' : '';
      const title = column.title ? ` title="${escapeHtml(column.title)}"` : '';
      return `<th${id}${classes ? ` class="${escapeHtml(classes)}"` : ''}${style}${sort}${title}>${column.label || ''}${column.sort === false ? '' : ' ↕'}</th>`;
    }).join('');

    const body = rows === null ? '' : rows.map((row, index) => {
      const hasData = number(row.matches) > 0 || number(row.points) > 0 || number(row.position) > 0 || Boolean(row.hasData);
      const computedPosition = number(row.position) || (hasData && table.autoRank ? index + 1 : null);
      const displayRow = { ...row, position: computedPosition };
      const zone = zoneForPosition(computedPosition, table.zones);
      const rowClass = zone?.rowClass || '';
      return `<tr${rowClass ? ` class="${escapeHtml(rowClass)}"` : ''}>${columns.map(column => {
        if (column.key === 'team') return teamCellMarkup(displayRow, table);
        if (column.key === 'position') {
          const rank = computedPosition ? `${computedPosition}º` : '—';
          const classes = computedPosition ? ['br-rank-marker', zone?.cellClass || ''].filter(Boolean).join(' ') : '';
          return `<td${classes ? ` class="${escapeHtml(classes)}"` : ''}${zone?.title ? ` title="${escapeHtml(zone.title)}"` : ''}>${rank}</td>`;
        }
        const classes = [column.className || '', column.hideMobile ? 'hide-mobile' : ''].filter(Boolean).join(' ');
        const style = column.accent ? ' style="color:var(--accent);font-weight:bold"' : '';
        return `<td${classes ? ` class="${escapeHtml(classes)}"` : ''}${style}>${escapeHtml(valueForColumn(displayRow, column, hasData))}</td>`;
      }).join('')}</tr>`;
    }).join('');

    return `${toggleButton}<div class="table-container"><table id="${escapeHtml(tableId)}"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
  }

  function renderClassification(config = {}) {
    const root = document.getElementById(config.rootId);
    if (!root) return false;
    const participants = config.participants || {};
    root.innerHTML = `<div class="ffws-season-classification-page${config.pageClass ? ` ${escapeHtml(config.pageClass)}` : ''}">
      <div class="ffws-season-centered">
        <h2>${escapeHtml(participants.title || 'Times Participantes')}</h2>
        ${participantsMarkup(participants)}
        ${formatMarkup(config.format)}
        <h2 class="ffws-season-classification-title">${escapeHtml(config.classificationTitle || 'Classificação Geral')}</h2>
        ${filterMarkup(config.filters)}
        ${tableMarkup(config.table)}
        ${config.afterTableHtml || ''}
      </div>
    </div>`;
    return true;
  }

  const api = Object.freeze({ renderClassification });
  window.FFWSBRSeasonEngine = api;
  window.FFWSBRSeasonLayout = api; // compatibilidade com chamadas anteriores
})();
